    },
    {
      "applicability": "moderate",
      "card_ids": ["C16"],
      "decision_effect": "no_change",
      "direction": "supportive",
      "family": "sigma receptor ligand SA4503"
    },
    {
      "applicability": "low",
      "card_ids": ["C21"],
      "decision_effect": "no_change",
      "direction": "contradictory",
      "family": "benzylpiperazine metabolite"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C15", "C13"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "BBB-permeable N-benzylpiperidine amides/indoles"
    },
    {
      "applicability": "low",
